insert into "weekly_buy_list" ("path", "hs_name", "week_slug", "week_start_date", "week_end_date", "model", "main_title", "page_subtitle", "page_date", "cover_image", "description", "is_published", "cio_content", "core_pct", "satellite_pct", "gfi_weight", "gfi_lt_return", "gfi_target_12m", "gfi_eps_12m", "gfi_funds", "geq_weight", "geq_lt_return", "geq_target_12m", "geq_eps_12m", "geq_funds", "sat_1_name", "sat_1_sub", "sat_1_weight", "sat_1_lt_return", "sat_1_target_12m", "sat_1_eps_12m", "sat_1_funds", "sat_2_name", "sat_2_sub", "sat_2_weight", "sat_2_lt_return", "sat_2_target_12m", "sat_2_eps_12m", "sat_2_funds", "sat_3_name", "sat_3_sub", "sat_3_weight", "sat_3_lt_return", "sat_3_target_12m", "sat_3_eps_12m", "sat_3_funds", "sat_4_name", "sat_4_sub", "sat_4_weight", "sat_4_lt_return", "sat_4_target_12m", "sat_4_eps_12m", "sat_4_funds", "sat_5_name", "sat_5_sub", "sat_5_weight", "sat_5_lt_return", "sat_5_target_12m", "sat_5_eps_12m", "sat_5_funds", "sat_6_name", "sat_6_sub", "sat_6_weight", "sat_6_lt_return", "sat_6_target_12m", "sat_6_eps_12m", "sat_6_funds", "sat_7_name", "sat_7_sub", "sat_7_weight", "sat_7_lt_return", "sat_7_target_12m", "sat_7_eps_12m", "sat_7_funds", "sat_8_name", "sat_8_sub", "sat_8_weight", "sat_8_lt_return", "sat_8_target_12m", "sat_8_eps_12m", "sat_8_funds", "perf_lt_return", "perf_core_return", "perf_sat_return", "perf_risk_sd", "perf_var_95", "source_text") values ('2026-08-17', 'Buy List ประจำสัปดาห์: จับตา FOMC Minute พร้อมเพิ่มน้ำหนัก Photonics และ BABA ในพอร์ต Satellite', '2026-08-17', '2026-08-17', '2026-08-21', 'Defender (30/70)', 'Buy List ประจำสัปดาห์: จับตา FOMC Minute พร้อมเพิ่มน้ำหนัก Photonics และ BABA ในพอร์ต Satellite', 'กองทุนแนะนำและกลยุทธ์จัดพอร์ตประจำสัปดาห์ 17–21 สิงหาคม 2569', '2026-08-17', '{"url": "https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/weekly-reports/2026-08-17/review-uploads/page_006.png", "altText": "", "type": "image"}'::jsonb, 'สัปดาห์นี้ Yuanta CIO ปรับพอร์ต Satellite เพิ่มน้ำหนัก Photonics และ BABA ขณะที่คอร์พอร์ตยังยึดมั่น Global Fixed Income และ Global Equity เป็นเสาหลัก', false, '<ul><li><span>สัปดาห์นี้จับตาการรายงาน FOMC Minute ของสหรัฐฯ หลังตัวเลขเศรษฐกิจโดยรวมเริ่มส่งสัญญาณชะลอตัว ตลอดจนการรายงาน GDP ญี่ปุ่น 2Q26 และการทยอยรายงานผลประกอบการของบริษัทจดทะเบียนในจีน และกลุ่มค้าปลีกของสหรัฐฯ</span></li><li><span>สำหรับการปรับพอร์ตโฟลิโอด้าน Satellite เราปรับคำแนะนำ PLTR06 และ ADVANT19 เหลือเพียง "Let profit run" และด้วยระดับราคาหุ้นในปัจจุบันไม่แนะนำให้เข้าลงทุนเพิ่มเติม โดยเรามีการเพิ่มสัดส่วนการลงทุนใน "BABA19" จากทิศทางการเติบโตของรายได้จาก Cloud service ที่มีแนวโน้มดีขึ้น</span></li><li><span>ในด้าน Semiconductor เรามีการเพิ่ม ETF LAZR และ DR COHR80, LITE80 เข้าไปตามลำดับหลังผลประกอบการกลุ่ม Photonics เริ่มมีทิศทางเติบโตที่ชัดเจนมากยิ่งขึ้น</span></li></ul>', 73, 27, 55, '4.5', NULL, NULL, 'UGISFX-N:mf, UGIS-N:mf, AGG:etf', 18, '8.52', '1218', '30.5', 'ES-GQG-UH:mf, ES-GQG:mf, WORLDA01:mf, ACWI:etf, DR:dr', 'Equity', 'Semi. Equity', 4, '12.88', NULL, NULL, 'SCBSEMI(A):mf, NVDA19:dr, SMH:etf', 'Equity', NULL, 1, '14.71', NULL, NULL, 'COHR80:dr, LITE80:dr, LAZR:etf', 'Equity', 'Smart GRID', 3, '10.86', NULL, NULL, 'A-GRID:mf, DAOL-VOLT:mf, VRT23:dr, GEV23:dr, GRID:etf, VOLT:etf, GEV80:dr, ETN23:dr', 'Equity', 'Software Equity', 3, '10.77', NULL, NULL, 'ORCL19:dr, IGV:etf, MSFT19:dr, BABA19:dr', 'Equity', 'Defend Equity', 3, '6.48', NULL, NULL, 'DAOL-DEFENSE:mf, SHLD:etf', 'Equity', 'JP Equity', 4, '7.06', '4338', '16.84', 'ASP-NGF:mf, KIOXIA23:dr, EWJ:etf, TEL80:dr', 'Equity', 'KR Equity', 4, '7.08', '9456', '209.51', 'SCBKEQTG:mf, MICRON19:dr, EWY:etf', 'Alternative', NULL, 5, '5', NULL, NULL, 'B-GOLD:mf, GOLD19:dr, GLD:etf', '6.42', '4.01', '2.01', '8.79', '-8.09', 'Source: Yuanta CIO, Bloomberg as of Aug 8, 2026 ; LT Return based on CME in-house model ; *MICRON19, SNDK80 ใช้แทน memory ธีมสำหรับ Satellite Portfolio
